using System.IO;
using UnityEditor;
using UnityEngine;

public class AlphaExtractionWindow : EditorWindow
{
    private Texture2D _textureOnWhite;
    private Texture2D _textureOnBlack;
    private string _outputPath = "";

    [MenuItem("Tools/Alpha Extraction/Extract from White & Black")]
    public static void ShowWindow()
    {
        var window = GetWindow<AlphaExtractionWindow>();
        window.titleContent = new GUIContent("Alpha Extractor");
        window.minSize = new Vector2(360, 200);
        window.Show();
    }

    private void OnGUI()
    {
        EditorGUILayout.LabelField("Rebuild alpha using two renders", EditorStyles.boldLabel);
        EditorGUILayout.Space();

        using (new EditorGUILayout.VerticalScope(EditorStyles.helpBox))
        {
            EditorGUILayout.LabelField("Source Textures", EditorStyles.label);
            _textureOnWhite = (Texture2D)EditorGUILayout.ObjectField("Image on White", _textureOnWhite, typeof(Texture2D), false);
            _textureOnBlack = (Texture2D)EditorGUILayout.ObjectField("Image on Black", _textureOnBlack, typeof(Texture2D), false);
        }

        using (new EditorGUILayout.VerticalScope(EditorStyles.helpBox))
        {
            EditorGUILayout.LabelField("Output", EditorStyles.label);
            EditorGUILayout.BeginHorizontal();
            EditorGUILayout.LabelField("PNG Path", GUILayout.Width(70));
            _outputPath = EditorGUILayout.TextField(_outputPath);
            if (GUILayout.Button("Browse", GUILayout.Width(70)))
            {
                var initialDirectory = string.IsNullOrEmpty(_outputPath)
                    ? Application.dataPath
                    : Path.GetDirectoryName(_outputPath) ?? Application.dataPath;
                var initialFileName = string.IsNullOrEmpty(_outputPath)
                    ? "AlphaExtraction.png"
                    : Path.GetFileName(_outputPath);

                var selected = EditorUtility.SaveFilePanel(
                    "Save Alpha Rebuilt Texture",
                    initialDirectory,
                    initialFileName,
                    "png");
                if (!string.IsNullOrEmpty(selected))
                {
                    _outputPath = selected;
                }
            }
            EditorGUILayout.EndHorizontal();
        }

        EditorGUILayout.Space();
        GUI.enabled = _textureOnWhite != null && _textureOnBlack != null;
        if (GUILayout.Button("Extract Alpha"))
        {
            RunExtraction();
        }
        GUI.enabled = true;
    }

    private void RunExtraction()
    {
        if (string.IsNullOrEmpty(_outputPath))
        {
            EditorUtility.DisplayDialog("Output Path Required", "Please choose where to save the generated PNG.", "OK");
            return;
        }

        try
        {
            var outputTexture = AlphaExtractionUtility.ExtractAlpha(_textureOnWhite, _textureOnBlack);
            AlphaExtractionUtility.SaveTextureToPng(outputTexture, _outputPath);
            EditorUtility.DisplayDialog("Extraction Complete", $"Saved texture to:\n{_outputPath}", "OK");
        }
        catch (System.Exception ex)
        {
            Debug.LogException(ex);
            EditorUtility.DisplayDialog("Extraction Failed", ex.Message, "OK");
        }
    }
}
